/// Keeps parent Fin visible while delivery runs, but removes completed child-stage work.
pub(crate) const TASK_ACTIVE_STAGE_PREDICATE: &str = "NOT (t.governed_stage AND EXISTS(SELECT 1 FROM task_subtasks child_stage JOIN tasks parent_stage ON parent_stage.id=child_stage.parent_task_id JOIN workflow_versions child_version ON child_version.id=t.workflow_version_id CROSS JOIN LATERAL jsonb_array_elements(child_version.graph->'states') child_state WHERE child_stage.child_task_id=t.id AND child_stage.removed_at IS NULL AND (child_stage.work_kind='decomposition' OR t.workflow_version_id=parent_stage.workflow_version_id) AND child_state->>'id'=t.state_id AND COALESCE((child_state->>'terminal')::boolean,false)))";
